  "{count} Abwesenheitsanträge warten auf deine Entscheidung.": {"en": "{count} absence requests are waiting for your decision.", "de": "{count} Abwesenheitsanträge warten auf deine Entscheidung.", "zh": "{count} 个缺勤申请等待你的决定。"},
  "{count} deiner Abwesenheitsanträge wurden genehmigt.": {"en": "{count} of your absence requests were approved.", "de": "{count} deiner Abwesenheitsanträge wurden genehmigt.", "zh": "你的 {count} 个缺勤申请已获批准。"},
  "{count} deiner Abwesenheitsanträge wurden abgelehnt.": {"en": "{count} of your absence requests were declined.", "de": "{count} deiner Abwesenheitsanträge wurden abgelehnt.", "zh": "你的 {count} 个缺勤申请已被拒绝。"},
