const messages = new Map<string, Record<Locale, string>>();
for (const [key, translations] of Object.entries(catalog)) {
  messages.set(key, translations);
  for (const text of Object.values(translations)) if (!messages.has(text)) messages.set(text, translations);
}
export function hasTranslation(message: string): boolean { return messages.has(message); }
export function translate(message: string, locale: Locale, values?: Record<string, string | number>): string {
  const template = messages.get(message)?.[locale] ?? message;
  return template.replace(/\{(\w+)\}/g, (token, key: string) => values && Object.hasOwn(values, key) ? (typeof values[key] === 'number' ? new Intl.NumberFormat(localeTag(locale)).format(values[key]) : values[key]) : token);
}
